import { defineQuery } from "next-sanity";

const IMG = `{
  "url": asset->url,
  "width": asset->metadata.dimensions.width,
  "height": asset->metadata.dimensions.height,
  "lqip": asset->metadata.lqip,
  alt,
  "hotspot": hotspot{x, y}
}`;

const SEO = `seo{ title, description, noIndex, "image": image${IMG} }`;

const SERVICE_REF = `{ name, "slug": slug.current, shortName, group }`;

const PROJECT_CARD = `{
  _id,
  name,
  "slug": slug.current,
  client,
  industry,
  year,
  order,
  summary,
  "services": services[]->${SERVICE_REF},
  "cover": cover${IMG},
  "cardImage": cardImage${IMG},
  "coverVideo": coverVideo{ "url": asset->url, "mimeType": asset->mimeType }
}`;

export const SETTINGS_QUERY = defineQuery(`*[_id == "siteSettings"][0]{
  siteTitle,
  "logo": logo${IMG},
  "logoOnDark": logoOnDark${IMG},
  footerLine,
  email,
  phone,
  location,
  "socialLinks": socialLinks[]{ _key, label, href },
  "menu": menu[]{ _key, label, href },
  headerButton{ label, href },
  dockButton{ label, href },
  cta{ heading, button{ label, href } },
  enquirySuccessMessage,
  seo{ title, description, "image": image${IMG}, googleVerification, bingVerification }
}`);

export const PAGE_QUERY = defineQuery(`*[_type == "page" && slug.current == $slug][0]{
  _id,
  title,
  "slug": slug.current,
  ${SEO},
  "sections": sections[]{
    ...,
    _type == "hero" => { button{ label, href } },
    _type == "projectGrid" => { link{ label, href } },
    _type == "showreel" => {
      "video": video{ "url": asset->url, "mimeType": asset->mimeType },
      "videoWebm": videoWebm{ "url": asset->url, "mimeType": asset->mimeType },
      "poster": poster${IMG}
    },
    _type == "featuredProject" => {
      "project": coalesce(
        project->${PROJECT_CARD},
        *[_id == "siteSettings"][0].featuredProject->${PROJECT_CARD}
      )
    }
  }
}`);

export const PAGE_SLUGS_QUERY = defineQuery(
  `*[_type == "page" && defined(slug.current)].slug.current`,
);

export const PROJECTS_QUERY = defineQuery(
  `*[_type == "project" && defined(slug.current)] | order(order asc, _createdAt desc) ${PROJECT_CARD}`,
);

export const PROJECT_QUERY = defineQuery(`*[_type == "project" && slug.current == $slug][0]{
  _id,
  name,
  "slug": slug.current,
  client,
  industry,
  year,
  order,
  "services": services[]->${SERVICE_REF},
  "cover": cover${IMG},
  "cardImage": cardImage${IMG},
  "coverVideo": coverVideo{ "url": asset->url, "mimeType": asset->mimeType },
  summary,
  tagline,
  location,
  "stats": coalesce(stats[]{ _key, value, label }, []),
  "story": coalesce(story[]{ _key, title, text }, []),
  result,
  liveUrl,
  "flow": select(defined(flow.video.asset) => flow{
    heading,
    "video": video{ "url": asset->url, "mimeType": asset->mimeType },
    "videoWebm": videoWebm{ "url": asset->url, "mimeType": asset->mimeType },
    "phone": phone{ "url": asset->url, "mimeType": asset->mimeType },
    "phoneWebm": phoneWebm{ "url": asset->url, "mimeType": asset->mimeType },
    "poster": poster{ "url": asset->url },
    "posterPhone": posterPhone{ "url": asset->url }
  }),
  "gallery": gallery[]{
    _key,
    "size": coalesce(size, "full"),
    "url": asset->url,
    "width": asset->metadata.dimensions.width,
    "height": asset->metadata.dimensions.height,
    "lqip": asset->metadata.lqip,
    alt,
    caption,
    heading,
    "hotspot": hotspot{x, y},
    "phone": phone{
      "url": asset->url,
      "width": asset->metadata.dimensions.width,
      "height": asset->metadata.dimensions.height,
      "lqip": asset->metadata.lqip
    }
  },
  ${SEO}
}`);

const SERVICE = `{
  _id,
  name,
  "slug": slug.current,
  shortName,
  group,
  order,
  tagline,
  description,
  "included": coalesce(included, []),
  note,
  statement,
  "benefits": coalesce(benefits[]{ _key, title, text }, []),
  "offerings": coalesce(offerings[]{ _key, title, text, "image": image${IMG} }, []),
  "faqs": coalesce(faqs[]{ _key, question, answer }, []),
  hero{ "image": image${IMG} },
  "card": card${IMG},
  "pageImage": pageImage${IMG},
  "pageImagePhone": pageImagePhone${IMG},
  clientsLabel,
  why{ label, heading, accent },
  stats{ label, "items": coalesce(items[]{ _key, value, label }, []) },
  offer{ label, heading, accent },
  steps{ label, heading, accent, "items": coalesce(items[]{ _key, title, text }, []) },
  related{ label, heading, accent },
  ${SEO}
}`;

export const SERVICES_QUERY = defineQuery(
  `*[_type == "service" && defined(slug.current)] | order(order asc) ${SERVICE}`,
);

const POST_CARD = `{
  _id,
  _updatedAt,
  title,
  "slug": slug.current,
  excerpt,
  category,
  publishedAt,
  demo,
  "chars": length(pt::text(body)),
  "cover": cover${IMG}
}`;

/** Every dated post, newest first; demo posts are filtered out where visitors see the list. */
export const POSTS_QUERY = defineQuery(
  `*[_type == "post" && defined(slug.current) && defined(publishedAt)] | order(publishedAt desc) ${POST_CARD}`,
);

export const POST_QUERY = defineQuery(`*[_type == "post" && slug.current == $slug && defined(publishedAt)][0]{
  ...${POST_CARD},
  "body": body[]{
    ...,
    _type == "image" => {
      _type,
      _key,
      caption,
      alt,
      "url": asset->url,
      "width": asset->metadata.dimensions.width,
      "height": asset->metadata.dimensions.height,
      "lqip": asset->metadata.lqip
    }
  },
  ${SEO}
}`);

export const SITEMAP_QUERY = defineQuery(`{
  "pages": *[_type == "page" && defined(slug.current) && seo.noIndex != true]{ "slug": slug.current, _updatedAt },
  "projects": *[_type == "project" && defined(slug.current) && seo.noIndex != true]{ "slug": slug.current, _updatedAt },
  "services": *[_type == "service" && defined(slug.current) && seo.noIndex != true]{ "slug": slug.current, _updatedAt },
  "posts": *[_type == "post" && defined(slug.current) && defined(publishedAt) && demo != true && seo.noIndex != true]{ "slug": slug.current, _updatedAt }
}`);
