import "server-only";
import { cache } from "react";
import type { QueryParams } from "next-sanity";
import { getClient } from "@/sanity/lib/client";
import { REVALIDATE_SECONDS } from "@/sanity/env";
import {
  PAGE_QUERY,
  PAGE_SLUGS_QUERY,
  POSTS_QUERY,
  POST_QUERY,
  PROJECTS_QUERY,
  PROJECT_QUERY,
  SERVICES_QUERY,
  SETTINGS_QUERY,
  SITEMAP_QUERY,
} from "@/sanity/lib/queries";
import {
  FEATURED_PROJECT_SLUG,
  PAGES,
  PROJECTS,
  SERVICES,
  SETTINGS,
} from "@/content/seed-data";
import { POSTS, readMinutes } from "@/content/blog";
import type {
  ComparisonSection,
  Page,
  Post,
  PostCard,
  ProcessSection,
  Project,
  ProjectCard,
  Service,
  SiteSettings,
} from "./types";

/**
 * Fetch published content. Results are cached and refreshed every
 * REVALIDATE_SECONDS (10s), so Studio changes reach the live site within seconds.
 * Returns undefined when no Sanity project is configured.
 */
async function sanityFetch<T>(query: string, params: QueryParams = {}): Promise<T | undefined> {
  const client = getClient();
  if (!client) return undefined;
  return client.fetch<T>(query, params, {
    next: { revalidate: REVALIDATE_SECONDS, tags: ["sanity"] },
  });
}

const toCard = (p: Project): ProjectCard => ({
  _id: p._id,
  name: p.name,
  slug: p.slug,
  client: p.client,
  industry: p.industry,
  year: p.year,
  services: p.services,
  cover: p.cover,
  cardImage: p.cardImage,
  coverVideo: p.coverVideo,
  order: p.order,
  summary: p.summary,
});

/** Drop null/undefined/empty values so defaults can fill the gaps. */
function present<T extends object>(obj: T | null | undefined): Partial<T> {
  if (!obj) return {};
  return Object.fromEntries(
    Object.entries(obj).filter(([, v]) => v !== null && v !== undefined && v !== "" && !(Array.isArray(v) && v.length === 0)),
  ) as Partial<T>;
}

export const getSettings = cache(async (): Promise<SiteSettings> => {
  const data = await sanityFetch<Partial<SiteSettings> | null>(SETTINGS_QUERY);
  const s = present(data);
  return {
    ...SETTINGS,
    ...s,
    socialLinks: s.socialLinks ?? SETTINGS.socialLinks,
    menu: s.menu ?? SETTINGS.menu,
    headerButton: { ...SETTINGS.headerButton, ...present(s.headerButton) },
    dockButton: { ...SETTINGS.dockButton, ...present(s.dockButton) },
    cta: {
      heading: s.cta?.heading || SETTINGS.cta.heading,
      button: { ...SETTINGS.cta.button, ...present(s.cta?.button) },
    },
    seo: {
      ...SETTINGS.seo,
      ...present(s.seo),
      image: s.seo?.image?.url ? s.seo.image : SETTINGS.seo.image,
    },
  };
});

/** Published CMS projects that have a cover image. */
const getCmsProjects = cache(async (): Promise<ProjectCard[]> => {
  const data = await sanityFetch<ProjectCard[]>(PROJECTS_QUERY);
  return (data ?? []).filter((p) => p.cover?.url);
});

/** CMS projects, or the starter projects until the dataset has been seeded. */
export const getProjects = cache(async (): Promise<ProjectCard[]> => {
  const projects = await getCmsProjects();
  return projects.length ? projects : PROJECTS.map(toCard);
});

export const getProject = cache(async (slug: string): Promise<Project | null> => {
  if ((await getCmsProjects()).length === 0) return PROJECTS.find((p) => p.slug === slug) ?? null;
  const data = await sanityFetch<Project | null>(PROJECT_QUERY, { slug });
  if (!data) return null;
  return {
    ...data,
    services: data.services ?? [],
    stats: data.stats ?? [],
    story: data.story ?? [],
    gallery: (data.gallery ?? []).filter((g) => g.url),
  };
});

/** CMS services, or the services from the brief until the dataset has been seeded. */
export const getServices = cache(async (): Promise<Service[]> => {
  const data = await sanityFetch<Service[]>(SERVICES_QUERY);
  return data?.length ? data : SERVICES;
});

export const getService = cache(async (slug: string): Promise<Service | null> => {
  const services = await getServices();
  return services.find((s) => s.slug === slug) ?? null;
});

function fallbackPage(slug: string): Page | null {
  const page = PAGES.find((p) => p.slug === slug);
  if (!page) return null;
  const featured = PROJECTS.find((p) => p.slug === FEATURED_PROJECT_SLUG);
  return {
    ...page,
    sections: page.sections.map((section) =>
      section._type === "featuredProject" && !section.project && featured
        ? { ...section, project: toCard(featured) }
        : section,
    ),
  };
}

/** A page by slug. Built-in pages fall back to the starter content until they exist in the CMS. */
export const getPage = cache(async (slug: string): Promise<Page | null> => {
  const data = await sanityFetch<Page | null>(PAGE_QUERY, { slug });
  if (data) return { ...data, sections: data.sections ?? [] };
  return fallbackPage(slug);
});

/** The “How we work” steps on the Services page, which every service page shows too. */
export const getProcess = cache(async (): Promise<ProcessSection | null> => {
  const page = await getPage("services");
  const section = page?.sections.find((s): s is ProcessSection => s._type === "process");
  return section?.steps?.length ? section : null;
});

/** The comparison table on the Services page, which every service page shows too. */
export const getComparison = cache(async (): Promise<ComparisonSection | null> => {
  const page = await getPage("services");
  const section = page?.sections.find((s): s is ComparisonSection => s._type === "comparison");
  return section?.rows?.length && section.columns?.length ? section : null;
});

export const getPageSlugs = cache(async (): Promise<string[]> => {
  const data = await sanityFetch<string[]>(PAGE_SLUGS_QUERY);
  return data ?? PAGES.map((p) => p.slug);
});

type CmsPostCard = Omit<PostCard, "readMinutes"> & { chars?: number | null };
const withReadTime = <T extends CmsPostCard>({ chars, ...p }: T) => ({ ...p, readMinutes: readMinutes(chars ?? 0) });
const toPostCard = ({ body, seo, ...card }: Post): PostCard => (void body, void seo, card);

/** CMS posts with a cover, newest first; the starter posts until the dataset has some. */
const getAllPosts = cache(async (): Promise<PostCard[]> => {
  const data = await sanityFetch<CmsPostCard[]>(POSTS_QUERY);
  const posts = (data ?? []).filter((p) => p.cover?.url).map(withReadTime);
  return posts.length ? posts : POSTS.map(toPostCard);
});

/** Posts for the blog. Demo posts only with `includeDemo` (the /blog/preview page). */
export async function getPosts({ includeDemo = false } = {}): Promise<PostCard[]> {
  const posts = await getAllPosts();
  return includeDemo ? posts : posts.filter((p) => !p.demo);
}

export const getPost = cache(async (slug: string): Promise<Post | null> => {
  const data = await sanityFetch<(CmsPostCard & Pick<Post, "body" | "seo">) | null>(POST_QUERY, { slug });
  if (data) return { ...withReadTime(data), body: (data.body ?? []).filter((b) => b._type !== "image" || ("url" in b && b.url)) };
  if ((await sanityFetch<CmsPostCard[]>(POSTS_QUERY))?.length) return null;
  return POSTS.find((p) => p.slug === slug) ?? null;
});

type SitemapEntry = { slug: string; _updatedAt?: string };

export async function getSitemapData(): Promise<{
  pages: SitemapEntry[];
  projects: SitemapEntry[];
  services: SitemapEntry[];
  posts: SitemapEntry[];
}> {
  const data = await sanityFetch<{ pages: SitemapEntry[]; projects: SitemapEntry[]; services: SitemapEntry[]; posts: SitemapEntry[] }>(
    SITEMAP_QUERY,
  );
  const starterPosts = POSTS.filter((p) => !p.demo).map((p) => ({ slug: p.slug }));
  if (data) return { ...data, posts: data.posts?.length ? data.posts : starterPosts };
  return {
    pages: PAGES.map((p) => ({ slug: p.slug })),
    projects: PROJECTS.map((p) => ({ slug: p.slug })),
    services: SERVICES.map((s) => ({ slug: s.slug })),
    posts: starterPosts,
  };
}
